define(["jquery"],function($){var c=function(f){var u=f.data("location-unsupported"),e=f.data("location-error");if(!navigator.geolocation){window.alert(u);return}var b=f.find("button[type='submit']");b.prop("disabled",true);navigator.geolocation.getCurrentPosition(function(p){f.find("input[name='latitude']").val(p.coords.latitude);f.find("input[name='longitude']").val(p.coords.longitude);f.find("input[name='accuracy']").val(p.coords.accuracy||"");f.attr("data-location-ready","1");f.get(0).submit()},function(){b.prop("disabled",false);window.alert(e)},{enableHighAccuracy:true,timeout:15000,maximumAge:0})};return{init:function(){$(document).on("submit","form[data-checkin-location-form='1']",function(e){var f=$(this);if(f.attr("data-location-ready")==="1")return;e.preventDefault();c(f)});$(document).on("submit","form[data-checkin-student-form='1']",function(e){var f=$(this);if(f.data("require-location")!==1||f.attr("data-location-ready")==="1")return;e.preventDefault();c(f)})}}});
